// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        vm.prank(0x000000000000000000000000000000000000bEEF, 0x000000000000000000000000000000000000bEEF);
        c = new SimpleWallet();
    }

    function _run(address caller) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(caller != address(0));
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        vm.assume(caller != owner);
        vm.assume(address(this).balance >= 0);
        caller = tx.origin;
        vm.assume(address(this) != c.owner());
        bool reverted;
        try c.withdraw(1) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == true);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable { }
}
